/// The row as JSON, keyed by physical column (riverbase relabels them).
#[must_use]
pub fn model_to_json(row: ModelRow) -> Value {
    json!({
        "_id": row._id.to_string(),
        "name": row.name,
        "provider": row.provider,
        "modalities": row.modalities,
        "capabilities": row.capabilities,
        "cost_per_1k_tokens": row.cost_per_1k_tokens,
        "max_tokens": row.max_tokens,
        "provider_config": row.provider_config,
        "extra": row.extra,
        "status": row.status,
        "_created": row._created.to_rfc3339(),
        "_updated": row._updated.map(|v| v.to_rfc3339()),
    })
}

/// The labels of `ref_beam.modelstatus`, in declaration order.
pub const MODELSTATUS: &[&str] = &["ACTIVE", "INACTIVE", "DEPRECATED"];

/// Write one `ref_beam.model` row from JSON keyed by physical column.
/// A new row is inserted, unless a concurrent insert of the same
/// `_id` won (then nothing changes). An existing row, soft-deleted or not,
/// gets only the columns `data` names, a new `_updated` and a new `_etag`.
/// `"_insert": true` leaves an existing row as it is (insert only);
/// `"_update": true` leaves a missing row missing (update only).
///
/// # Errors
/// `BEM-146` for a value of the wrong type or an unknown enum label;
/// database errors.
pub async fn upsert_model(conn: &mut AsyncPgConnection, id: Uuid, data: &Value) -> DataResult<()> {
    let v_name = take::<String>(data, "name")?;
    let v_provider = take::<String>(data, "provider")?;
    let v_modalities = take::<Value>(data, "modalities")?;
    let v_capabilities = take::<Value>(data, "capabilities")?;
    let v_cost_per_1k_tokens = take::<f64>(data, "cost_per_1k_tokens")?;
    let v_max_tokens = take::<i32>(data, "max_tokens")?;
    let v_provider_config = take::<Value>(data, "provider_config")?;
    let v_extra = take::<Value>(data, "extra")?;
    let v_status = take::<String>(data, "status")?
        .map(|v| {
            enum_sql::<diesel::sql_types::Text>(
                Some(v.as_str()),
                "status",
                "modelstatus",
                MODELSTATUS,
            )
        })
        .transpose()?;
    let flag = |key: &str| data.get(key).and_then(Value::as_bool) == Some(true);
    let exists: bool = if flag("_insert") {
        false
    } else {
        diesel_async::RunQueryDsl::get_result(
            diesel::select(diesel::dsl::exists(model::table.filter(model::_id.eq(id)))),
            conn,
        )
        .await?
    };
    if exists {
        diesel_async::RunQueryDsl::execute(
            diesel::update(model::table.filter(model::_id.eq(id))).set((
                v_name.map(|v| model::name.eq(v)),
                v_provider.map(|v| model::provider.eq(v)),
                v_modalities.map(|v| model::modalities.eq(v)),
                v_capabilities.map(|v| model::capabilities.eq(v)),
                v_cost_per_1k_tokens.map(|v| model::cost_per_1k_tokens.eq(v)),
                v_max_tokens.map(|v| model::max_tokens.eq(v)),
                v_provider_config.map(|v| model::provider_config.eq(v)),
                v_extra.map(|v| model::extra.eq(v)),
                v_status.map(|v| model::status.eq(v)),
                model::_updated.eq(diesel::dsl::sql::<
                    diesel::sql_types::Nullable<diesel::sql_types::Timestamptz>,
                >("now()")),
                model::_etag.eq(Uuid::new_v4()),
            )),
            conn,
        )
        .await?;
    } else if !flag("_update") {
        diesel_async::RunQueryDsl::execute(
            diesel::insert_into(model::table)
                .values((
                    model::_id.eq(id),
                    v_name.map(|v| model::name.eq(v)),
                    v_provider.map(|v| model::provider.eq(v)),
                    v_modalities.map(|v| model::modalities.eq(v)),
                    v_capabilities.map(|v| model::capabilities.eq(v)),
                    v_cost_per_1k_tokens.map(|v| model::cost_per_1k_tokens.eq(v)),
                    v_max_tokens.map(|v| model::max_tokens.eq(v)),
                    v_provider_config.map(|v| model::provider_config.eq(v)),
                    v_extra.map(|v| model::extra.eq(v)),
                    v_status.map(|v| model::status.eq(v)),
                ))
                .on_conflict(model::_id)
                .do_nothing(),
            conn,
        )
        .await?;
    }
    Ok(())
}

